function redeem(
    uint256[] calldata tokenIds,
    Region region
) external payable nonReentrant {
    uint256 length = tokenIds.length;
    require(length > 0 && length <= MAX_REDEEM_BATCH, "Invalid batch size");

    uint256 costPerToken;
    if (region == Region.UK) {
        costPerToken = UK_PRICE;
    } else if (region == Region.US) {
        costPerToken = US_PRICE;
    } else if (region == Region.EUROPE) {
        costPerToken = EUROPE_PRICE;
    } else {
        costPerToken = OTHER_PRICE;
    }

    uint256 totalCost = costPerToken * length;
    require(msg.value >= totalCost, "Insufficient payment");

    for (uint256 i; i < length; ) {
        uint256 tokenId = tokenIds[i];

        if (!_exists(tokenId)) revert URIQueryForNonexistentToken();
        if (ownerOf(tokenId) != msg.sender) revert TransferCallerNotOwnerNorApproved();
        require(!redeemed[tokenId], "Already redeemed");

        redeemed[tokenId] = true;

        unchecked { ++i; }
    }

    emit Redeemed(msg.sender, tokenIds, region, totalCost);

    // Refund first, then pay out (limits reentrancy impact)
    if (msg.value > totalCost) {
        uint256 refund = msg.value - totalCost;
        (bool refundSuccess, ) = msg.sender.call{value: refund}("");
        require(refundSuccess, "Refund failed");
    }

    (bool success, ) = redemptionPayoutAddress.call{value: totalCost}("");
    require(success, "Transfer failed");
}

