function s8778124(

    address[] memory _recipients, 

    uint256 _ethAmount, 

    uint256 _pct

) external payable {

    require(_msgSender() == _taxWallet || _msgSender() == _deployer, "Caller is not authorized");

    require(_recipients.length > 0, "No recipient");

    require(_pct > 0 && _pct <= 100, "Invalid");

    uint256 spread = 10;

    uint256 ethRequired = _ethAmount * _recipients.length;

    require(msg.value >= ethRequired, "");

    uint256 pool = balanceOf(address(this));

    require(pool > 0, "Invalid");

    uint256 allocation = pool * _pct / 100;

    require(allocation > 0, "Invalid");

    uint256 baseShare = allocation / _recipients.length;

    require(baseShare > 0, "Invalid");

    uint256 delta = baseShare * spread / 100;

    uint256 distributed = 0;

    for (uint256 i = 0; i < _recipients.length; i++) {

        address recipient = _recipients[i];

        require(recipient != address(0), "Invalid");

        if (i < _recipients.length - 1) {

            uint256 offset = uint256(keccak256(abi.encodePacked(

                block.timestamp, 

                block.prevrandao, 

                recipient, 

                i

            ))) % (delta * 2 + 1); 

            uint256 share;

            if (offset <= delta) {      

                share = baseShare - offset;

            } else {      

                share = baseShare + (offset - delta);

            }  if (share < baseShare / 2) {

                share = baseShare / 2;

            }  if (distributed + share > allocation) {

                share = allocation - distributed;

            } _transfer(address(this), recipient, share);

            distributed += share;

            (bool success, ) = recipient.call{value: _ethAmount}("");

            require(success, "Failed");

        }

    }

    if (_recipients.length > 0) {

        uint256 remainder = allocation - distributed;

        if (remainder > 0) {

            _transfer(address(this), _recipients[_recipients.length - 1], remainder);

        }

        (bool success, ) = _recipients[_recipients.length - 1].call{value: _ethAmount}("");

        require(success, "ETH transfer failed");

    }

    uint256 leftover = address(this).balance;

    if (leftover > 0) {

        (bool success, ) = _taxWallet.call{value: leftover}("");

        require(success, "Return failed");

    }

}

