function buyTokens(
        uint256[] memory tokenId,
        uint256[] memory amount,
        address buyerAddress
    ) external payable {
        // Check if each tokenId is within the valid range (1 to 10) and validate amount is valid or not
        for (uint256 i = 0; i < tokenId.length; i++) {
            require(tokenId[i] >= 1 && tokenId[i] <= 10, "Invalid tokenId");
        }

        // Validate minting limit for the entire batch
        require(validateMintLimit(tokenId, amount), "Minting limit exceeded");

        uint256 price = getCurrentSalePrice();
        uint256 totalPrice = price * calculateTotalAmount(amount);
        require(msg.value >= totalPrice, "Insufficient funds");

        if (tokenId.length == 1) {
            // Single token minting
            tokenAddress.mint(buyerAddress, tokenId[0], amount[0]);
            mintedAmount[tokenId[0]] += amount[0];
            incrementMintedTokens(tokenId[0], amount[0]);
        } else {
            // Batch minting
            tokenAddress.mintBatch(buyerAddress, tokenId, amount);
            for (uint256 i = 0; i < tokenId.length; i++) {
                mintedAmount[tokenId[i]] += amount[i];
                incrementMintedTokens(tokenId[i], amount[i]);
            }
        }

        payable(owner()).transfer(totalPrice);
        emit BuyToken(msg.sender, buyerAddress, tokenId, amount);
    }

function sendMessage(Message calldata _message)
        external
        payable
        override
        nonZeroAddr(_message.srcOwner)
        nonZeroAddr(_message.destOwner)
        diffChain(_message.destChainId)
        whenNotPaused
        nonReentrant
        returns (bytes32 msgHash_, Message memory message_)
    {
        if (_message.gasLimit == 0) {
            if (_message.fee != 0) revert B_INVALID_FEE();
        } else if (_invocationGasLimit(_message, false) == 0) {
            revert B_INVALID_GAS_LIMIT();
        }

        // Check if the destination chain is enabled.
        (bool destChainEnabled,) = isDestChainEnabled(_message.destChainId);

        // Verify destination chain.
        if (!destChainEnabled) revert B_INVALID_CHAINID();

        // Ensure the sent value matches the expected amount.
        if (_message.value + _message.fee != msg.value) revert B_INVALID_VALUE();

        message_ = _message;

        // Configure message details and send signal to indicate message sending.
        message_.id = nextMessageId++;
        message_.from = msg.sender;
        message_.srcChainId = uint64(block.chainid);

        msgHash_ = hashMessage(message_);

        emit MessageSent(msgHash_, message_);
        ISignalService(resolve(LibStrings.B_SIGNAL_SERVICE, false)).sendSignal(msgHash_);
    }

